"""Offline progressive enhancement; SVG and exact frozen source remain authoritative."""
import json,html
def viewer(svg,spec,input_hash):
    ids=[r['id'] for r in spec['data']['objects']];groups=spec['data']['groups'];payload=json.dumps({'ids':ids,'groups':groups,'source_sha256':input_hash},ensure_ascii=False).replace('<','\\u003c')
    return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; connect-src 'none'"><title>Frozen linked evidence</title><style>body{font:15px Arial;background:#edf2f6;color:#20354b;margin:24px}header{position:sticky;top:0;background:white;padding:14px;border:1px solid #dbe4ea;z-index:2}button,input,select{font:inherit;margin:4px;padding:7px}svg{display:block;width:min(100%,1100px);height:auto;margin:18px auto;background:white}button:focus,input:focus,select:focus{outline:3px solid #197f86}.dim{opacity:.10}.selected circle{stroke:#172b4d;stroke-width:1.4}#status{padding:8px}details{background:white;padding:12px}</style><header><strong>Frozen evidence · matched identities</strong><br><label>Find object <input id="search" placeholder="Exact ID or prefix"></label><label>Group <select id="group"><option value="">All groups</option>'''+''.join('<option>'+html.escape(g)+'</option>' for g in groups)+'''</select></label><button id="clear">Clear selection</button><button id="download">Download highlighted SVG + scope</button><div id="status" role="status" aria-live="polite"></div><small>Tab to cells; Enter or Space toggles selection. Selected cells appear in every corresponding marker panel. All unselected objects remain visible as context.</small></header><main>'''+svg+'''</main><details><summary>Accessible source table</summary><table><thead><tr><th>Object</th><th>Group</th><th>Donor</th><th>Stored x</th><th>Stored y</th></tr></thead><tbody>'''+''.join('<tr>'+''.join('<td>'+html.escape(str(o[k]))+'</td>' for k in ('id','group','donor','x','y'))+'</tr>' for o in spec['data']['objects'])+'''</tbody></table></details><script>const meta='''+payload+''';const selected=new Set();const nodes=[...document.querySelectorAll('[data-object]')];let visibleIds=[];function update(){const q=document.querySelector('#search').value.toLowerCase(),g=document.querySelector('#group').value;visibleIds=meta.ids.filter(id=>nodes.find(n=>n.dataset.object===id&&(!g||n.dataset.group===g))&&id.toLowerCase().includes(q));const keep=new Set(visibleIds);nodes.forEach(n=>{n.classList.toggle('dim',!keep.has(n.dataset.object)||(selected.size>0&&!selected.has(n.dataset.object)));n.classList.toggle('selected',selected.has(n.dataset.object));n.setAttribute('aria-pressed',selected.has(n.dataset.object)?'true':'false');});document.querySelector('#status').textContent=`${meta.ids.length} total objects · ${visibleIds.length} match · ${selected.size} selected; unselected objects retained as context`;}function toggle(id){if(selected.has(id))selected.delete(id);else selected.add(id);update();}nodes.forEach(n=>{n.setAttribute('role','button');n.addEventListener('click',()=>toggle(n.dataset.object));n.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle(n.dataset.object);}});});document.querySelector('#search').addEventListener('input',update);document.querySelector('#group').addEventListener('change',update);document.querySelector('#clear').onclick=()=>{selected.clear();update();};function save(data,name,type){let a=document.createElement('a'),u=URL.createObjectURL(new Blob([data],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}document.querySelector('#download').onclick=async()=>{let clone=document.querySelector('svg').cloneNode(true);clone.querySelectorAll('[data-object]').forEach(n=>n.removeAttribute('tabindex'));let xml=new XMLSerializer().serializeToString(clone);let bytes=new TextEncoder().encode(xml);let hash=await crypto.subtle.digest('SHA-256',bytes);let outHash=[...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('');save(xml,'highlighted.svg','image/svg+xml');save(JSON.stringify({schema:'frozen-highlight-scope/1',source_sha256:meta.source_sha256,svg_sha256:outHash,selected_ids:[...selected],matching_ids:visibleIds,all_ids:meta.ids,background_objects_retained:true,coordinates_and_scales_changed:false,visual_acceptance:false},null,2),'highlighted.scope.json','application/json');};update();</script></html>'''
